-- Read only: bounded metadata projection of already-collected public records.
select jsonb_agg(jsonb_build_object('platform',r.platform,'actor',r.actor,'run_id',r.run_id,'account_id',r.account_id,'external_id',r.external_id,'public_payload',jsonb_strip_nulls((select jsonb_object_agg(e.key,e.value) from jsonb_each(r.payload) e where e.key=any(array['id','shortCode','type','url','caption','ownerUsername','ownerId','inputUrl','timestamp','hashtags','mentions','likesCount','commentsCount','videoViewCount','videoPlayCount','productType','displayUrl','uri','name','description','link','created_time','release_time','duration','privacy']))))) as public_samples from (select * from ingest.raw_items where run_id in ('f77352da-6efb-4d33-bacb-2e2f8826dd37','d0c86952-df68-48ff-8f41-132500e2e90b') order by platform,account_id,id limit 30) r;